/*
 * A214281  Triangle by rows, row n contains the ConvOffs transform of the
 *          first n terms of 1, 1, 3, 2, 5, 3, 7, ... (A026741 without leading
 *          zero).
 * https://oeis.org/A214281
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is generated by flattening the triangle whose row t (t ≥ 1)
 *            is the ConvOffs transform of the first t terms of
 *            s(0),s(1),…,s(t−1) with s(2k) = 2k+1 (even index) s(2k+1) = k+1
 *            (odd index). The transform is defined by a0 = 1 a_i = a_{i-1} *
 *            s(t-i-1) / s(i-1) for 1 ≤ i < t The algorithm builds r...
 * Range:     u8 n <= 49, u16 n <= 77, u32 n <= 77, u64 n <= 77, u128 n <= 77,
 *            big any n
 * Helpers:   base_s
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/base_s.h"

/* static cache for the flattened triangle */
static seq_t *cache = NULL;          /* pointer to cached values      */
static size_t cache_len   = 0;        /* number of values stored       */
static size_t cache_cap   = 0;        /* allocated capacity in seq_t   */
static idx_t  next_row_len = 1;       /* length of the next row to generate */

/* grow the cache to hold at least 'needed' elements */
static inline void grow_cache(size_t needed)
{
    if (cache_cap >= needed)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < needed)
        new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp)
        abort();                      /* unrecoverable memory failure */
    cache = tmp;
    cache_cap = new_cap;
}

/* generate the next row of length 't' and append it to the cache */
static void generate_row(idx_t t)
{
    seq_t a_prev = 1;
    grow_cache(cache_len + 1);
    cache[cache_len++] = a_prev;      /* a_0 of the row */

    for (idx_t i = 1; i < t; ++i) {
        seq_t num = a_prev * base_s(t - i - 1);
        seq_t den = base_s(i - 1);
        seq_t a_i  = num / den;
        grow_cache(cache_len + 1);
        cache[cache_len++] = a_i;
        a_prev = a_i;
    }
}

/* public entry point */
seq_t a(idx_t n)
{
    /* ensure the cache contains at least n+1 elements */
    while (cache_len <= n) {
        generate_row(next_row_len);
        ++next_row_len;
    }
    return cache[n];
}
